/**
 * Two players on one device: the game setup, a new game, then day after day until one side
 * is beaten. Behind the setup dialog, a world generated by the engine is shown in full.
 */
import { GLOBALS_SIZE, Mem } from "../../engine/src/mem.ts";
import {
  AUTOSAVE_OFF, COMPUTER_FLAG, DAY, GAME_MODE, GAME_SEED, LOCAL_PLAYER, NET_TURN, SKILL,
} from "../../engine/src/globals.ts";
import { DayLoop, runDay, setUpControllers } from "../../engine/src/day.ts";
import { initGlobals } from "../../engine/src/launch.ts";
import { playerMap } from "../../engine/src/map.ts";
import { generateMap } from "../../engine/src/mapgen.ts";
import { newGame } from "../../engine/src/newgame.ts";
import { BrowserHost } from "./host.ts";
import { Input } from "./input.ts";
import { UI } from "./ui.ts";
import { MapView } from "./view.ts";

const ui = new UI();
const canvas = document.getElementById("map") as HTMLCanvasElement;
const view = new MapView(canvas);
const input = new Input();
input.attach(view, () => ui.modal);
const host = new BrowserHost(ui, view, input);
for (const button of document.querySelectorAll<HTMLButtonElement>("#commands button")) {
  button.addEventListener("click", () => input.push({ kind: "key", key: button.dataset.key ?? "" }));
}

/** A world for the setup screen to show. */
function preview(): void {
  const m = new Mem(new Uint8Array(GLOBALS_SIZE));
  initGlobals(m);
  m.setB(SKILL, 5);
  m.setL(GAME_SEED, (Math.random() * 0x100000000) >>> 0);
  generateMap(m);
  view.revealAll = true;
  view.draw(m);
  ui.mapWrap.scrollLeft = (canvas.clientWidth - ui.mapWrap.clientWidth) / 2;
  ui.mapWrap.scrollTop = (canvas.clientHeight - ui.mapWrap.clientHeight) / 2;
}

async function play(): Promise<void> {
  preview();
  const skill = await ui.setup();
  view.revealAll = false;

  const m = new Mem(new Uint8Array(GLOBALS_SIZE));
  initGlobals(m);
  m.setB(GAME_MODE, 1);
  m.setB(SKILL, skill);
  m.setB(playerMap(1) + COMPUTER_FLAG, 0);
  m.setB(playerMap(2) + COMPUTER_FLAG, 0);
  m.setB(LOCAL_PLAYER, 1);
  m.setB(NET_TURN, 1);
  m.setW(DAY, 1);
  await newGame(m, host);
  m.setB(AUTOSAVE_OFF, 1);
  setUpControllers(m);

  const loop = new DayLoop();
  for (;;) {
    const end = await runDay(m, host, loop);
    host.redraw(m);
    if (end.p1Defeated) {
      await ui.notice("Player 2 wins", "Player 1 has been beaten.", "New game");
      return;
    }
    if (end.p2Surrenders) {
      const accept = await ui.ask("Player 2 offers to surrender",
        "Player 2 has lost too much to fight on. Accept the surrender?", "Accept", "Keep fighting");
      if (accept) {
        await ui.notice("Player 1 wins", "Player 2 has surrendered.", "New game");
        return;
      }
    }
  }
}

async function main(): Promise<void> {
  for (;;) {
    try {
      await play();
    } catch (e) {
      console.error(e);
      await ui.notice("Something went wrong", e instanceof Error ? e.message : String(e), "Start again");
    }
  }
}

void main();
